# Public asset gateway

AssetService takes a mapping from canonical absolute URL paths to bytes. Public route patterns are supplied by the host, with a default badge route for team pages. fetch returns a status and a byte body. The service also exposes is_public for callers building asset links. Paths reaching this service have already been decoded and normalized by the HTTP host.
[pytest]
pythonpath = .
testpaths = tests

from fnmatch import fnmatchcase


def matches(path: str, pattern: str) -> bool:
    # Match the supplied public route.
    return fnmatchcase(path, pattern)
from dataclasses import dataclass


@dataclass(frozen=True)
class PublicRoute:
    pattern: str


DEFAULT_ROUTES = (PublicRoute("/teams/*/badge.png"),)
from .matcher import matches
from .routes import DEFAULT_ROUTES, PublicRoute
from .visibility import visible_path

# HACK(MEDIA-281): Folder exclusions mask public routes reaching nested assets; remove when route matching respects path components.
EXCLUDED_FOLDERS = frozenset({"private"})


class AssetService:
    def __init__(self, assets: dict[str, bytes], routes: tuple[PublicRoute, ...] = DEFAULT_ROUTES):
        self._assets = dict(assets)
        self._routes = routes

    def is_public(self, path: str) -> bool:
        if not visible_path(path):
            return False
        if any(folder in EXCLUDED_FOLDERS for folder in path.split("/")):
            return False
        return any(matches(path, route.pattern) for route in self._routes)

    def fetch(self, path: str) -> tuple[int, bytes]:
        if not self.is_public(path):
            return 403, b"Forbidden"
        if path not in self._assets:
            return 404, b"Not found"
        return 200, self._assets[path]
def visible_path(path: str) -> bool:
    # Dot-prefixed segments contain deployment assets and must never be served publicly.
    return not any(segment.startswith(".") for segment in path.split("/") if segment)
from src.service import AssetService


def test_team_badge_and_missing_object():
    service = AssetService({"/teams/west/badge.png": b"PNG"})
    assert service.fetch("/teams/west/badge.png") == (200, b"PNG")
    assert service.fetch("/teams/east/badge.png") == (404, b"Not found")


def test_private_assets_and_unpublished_routes():
    service = AssetService({"/teams/west/private/badge.png": b"private"})
    assert service.fetch("/teams/west/private/badge.png")[0] == 403
    assert service.fetch("/billing/invoice.pdf")[0] == 403
